from pathlib import Path
import subprocess,tempfile,os
r=Path(__file__).resolve().parents[1]
harness='\n#include <assert.h>\n#include <stdio.h>\n#include <string.h>\n#include <stdbool.h>\nvoid (*test_work)(void *);void *test_arg;int test_task_fail,test_memory_fail;\n#define MESH_DRAFT_PATH "async-drafts.bin"\n#include "draft_store.c"\nstatic mesh_draft_t drafts[MESH_DRAFT_LIMIT],loaded[MESH_DRAFT_LIMIT];\nstatic uint32_t replies[MESH_DRAFT_LIMIT],loaded_replies[MESH_DRAFT_LIMIT];\nstatic void work(void){assert(test_work);void (*f)(void *)=test_work;test_work=NULL;f(test_arg);}\nint main(void){\n size_t count;bool recovered,ok;\n assert(mesh_draft_store_load(loaded,loaded_replies,MESH_DRAFT_LIMIT,&count,&recovered));\n strcpy(drafts[0].text,"original 🙂");replies[0]=123;\n test_memory_fail=1;assert(!mesh_draft_store_start(drafts,replies,1)&&!mesh_draft_store_busy());test_memory_fail=0;\n test_task_fail=1;assert(!mesh_draft_store_start(drafts,replies,1)&&!mesh_draft_store_busy());test_task_fail=0;\n assert(mesh_draft_store_start(drafts,replies,1)&&mesh_draft_store_busy()&&!mesh_draft_store_poll(&ok));\n strcpy(drafts[0].text,"changed during save");replies[0]=456;\n assert(!mesh_draft_store_start(drafts,replies,1));work();assert(mesh_draft_store_busy()&&mesh_draft_store_poll(&ok)&&ok);\n assert(mesh_draft_store_load(loaded,loaded_replies,MESH_DRAFT_LIMIT,&count,&recovered)&&count==1&&!strcmp(loaded[0].text,"original 🙂")&&loaded_replies[0]==123);\n assert(mesh_draft_store_start(drafts,replies,1));work();mesh_draft_store_poll(&ok);assert(ok);\n assert(mesh_draft_store_load(loaded,loaded_replies,MESH_DRAFT_LIMIT,&count,&recovered)&&!strcmp(loaded[0].text,"changed during save")&&loaded_replies[0]==456);\n puts("PASS: production ESP deferred draft worker, immutable text/reply snapshot, busy/completion lifecycle, PSRAM/task failures and subsequent save");return 0;\n}\n'
with tempfile.TemporaryDirectory() as d:
 p=Path(d);(p/'freertos').mkdir();(p/'pax_gfx.h').write_text('#pragma once\ntypedef struct {int unused;} pax_buf_t;\n')
 (p/'esp_heap_caps.h').write_text('#pragma once\n#include <stdlib.h>\nextern int test_memory_fail;\n#define MALLOC_CAP_SPIRAM 1\n#define MALLOC_CAP_8BIT 2\nstatic inline void *heap_caps_malloc(size_t n,int caps){assert(n<=50000);return test_memory_fail?NULL:malloc(n);}\n')
 (p/'freertos/FreeRTOS.h').write_text('#pragma once\n#define pdPASS 1\n#define tskIDLE_PRIORITY 0\n')
 (p/'freertos/task.h').write_text('#pragma once\nextern void (*test_work)(void *);extern void *test_arg;extern int test_task_fail;\nstatic inline int xTaskCreate(void (*f)(void *),const char *n,unsigned stack,void *arg,unsigned priority,void *handle){assert(stack>=8*1024&&priority==1);if(test_task_fail)return 0;test_work=f;test_arg=arg;return 1;}\nstatic inline void vTaskDelete(void *t){}\n')
 (p/'test.c').write_text(harness)
 subprocess.run(['clang','-std=c11','-fsanitize=address,undefined','-DESP_PLATFORM','-I',d,'-I',str(r/'tests/stubs'),'-I',str(r/'main'),str(p/'test.c'),'-o',str(p/'test')],check=True)
 subprocess.run([str(p/'test')],cwd=d,env=dict(os.environ,TZ='Pacific/Honolulu'),check=True)
